    return G
G=load()

dp3_in = G['Demo pair 3 input']
dp3_out = G['Demo pair 3 output']

h_in, w_in = len(dp3_in), len(dp3_in[0])
h_out, w_out = len(dp3_out), len(dp3_out[0])

print("Finding row repeats in Demo 3 output:\n")
for i in range(h_out):
    for j in range(i+1, h_out):
        if dp3_out[i] == dp3_out[j]:
            print(f"Row {i} = Row {j}: {dp3_out[i]}")

print("\n\nUnique rows in output:")
unique_rows = []
for r in dp3_out:
    if r not in unique_rows:
        unique_rows.append(r)
        print(f"{len(unique_rows)}. {r}")

dp2_in = G['Demo pair 2 input']
dp2_out = G['Demo pair 2 output']

print("Type A rows (first char 8):")
for r in [0, 3, 4]:
    print(f"  Out[{r}][:15] = {dp2_out[r][:15]}")
    # Check if it's In[1][::-1]
    if dp2_out[r][:15] == dp2_in[1][::-1]:
        print(f"    ^ Matches In[1][::-1]")

print("\nType B rows (first char 9):")  
for r in [1, 2, 5]:
    print(f"  Out[{r}][:15] = {dp2_out[r][:15]}")
    # Check if it's In[0][::-1]
    if dp2_out[r][:15] == dp2_in[0][::-1]:
        print(f"    ^ Matches In[0][::-1]")

print("\nSecond halves of all rows:")
for r in range(6):
    second_half = dp2_out[r][15:]
    print(f"  Out[{r}][15:]: {second_half}")
    if second_half == dp2_in[1]:
        print(f"    ^ Matches In[1]")

dp3_in = G['Demo pair 3 input']
dp3_out = G['Demo pair 3 output']

# Check what pattern generates the src_map
src_map = []
for r in range(len(dp3_out)):
    for i in range(len(dp3_in)):
        if dp3_out[r][:len(dp3_in[0])] == dp3_in[i][::-1]:
            src_map.append(i)
            break

print("Source mapping sequence:")
print(src_map)

# Can we see a pattern?
# Check modulo patterns
for mod in [3, 2, 1]:
    print(f"\nPattern with mod={mod}:")
    seen = {}
    for r, s in enumerate(src_map):
        key = r % mod
        val = s
        if key not in seen:
            seen[key] = val
    for k, v in sorted(seen.items()):
        print(f"  r%{mod}=={k}: src={v}")

